public interface Notifier {
    void send(String recipient, String message);
}

@Component
@Profile("dev")
public class LoggingNotifier implements Notifier {
    public void send(String recipient, String message) {
        System.out.println("[DEV] Would notify " + recipient + ": " + message);
    }
}

@Component
@Profile("prod")
public class SesNotifier implements Notifier {
    private final AmazonSimpleEmailService sesClient;
    public SesNotifier(AmazonSimpleEmailService sesClient) { this.sesClient = sesClient; }

    public void send(String recipient, String message) {
        // ... real AWS SES call using sesClient ...
    }
}

